void Init(JNIEnv *env, jobject thiz, jobject ctx, jobject title, jobject subtitle) {
    //Set sub title
    setText(env, title, OBFUSCATE("<b>Modded by yoshiswagg</b>"));

    //Set sub title
    setText(env, subtitle, OBFUSCATE("<b><marquee><p style=\"font-size:30\">"
                                     "<p style=\"color:green;\">CHWALA POLSCE</p> | "
                                     "Modded by yoshiswagg | Special thanks to BruhceMain!</p>"
                                     "</marquee></b>"));

    //Dialog Example
    Dialog(env,
           ctx,
           OBFUSCATE("Unfinished Menu"),
           OBFUSCATE("This menu is yet to be finished, so expect bugs or other issues!"),
           nullptr, // set nullptr if btn-link is not needed
           OBFUSCATE("Start"),
           0, // set 0 if auto-close is not needed
           nullptr); // set nullptr if btn-link is not needed

    //Toast Example
    Toast(env, ctx, OBFUSCATE("Modded by yoshiswagg"), ToastLength::LENGTH_LONG);
}

